class ThreadPoolExecutor(futures.ThreadPoolExecutor):
    def __init__(
        self,
        max_workers=None,
        thread_name_prefix="",
        initializer=None,
        initargs=(),
        cancel_on_error=False,
    ):
        """Initializes a new ThreadPoolExecutor instance.

        Args:
            max_workers: The maximum number of threads that can be used to
                execute the given calls.
            thread_name_prefix: An optional name prefix to give our threads.
            initializer: A callable used to initialize worker threads.
            initargs: A tuple of arguments to pass to the initializer.
            cancel_on_error: If True, pending futures will be cancelled when an
                exception occurs in the context manager or in any of the futures.
        """
        super().__init__(
            max_workers=max_workers,
            thread_name_prefix=thread_name_prefix,
            initializer=initializer,
            initargs=initargs,
        )
        self._cancel_on_error = cancel_on_error
        self._futures = set()
        self._lock = threading.Lock()
        self._error_occurred = False
        self._first_exception = None

    def submit(self, fn, *args, **kwargs):
        """Submit a callable to be executed with the given arguments.

        Extends the parent class's submit method to track futures and handle errors.
        """
        with self._lock:
            # If an error has already occurred and cancel_on_error is True,
            # don't submit new tasks
            if self._cancel_on_error and self._error_occurred:
                f = futures.Future()
                f.cancel()
                return f

            # Create a wrapper function that will catch exceptions
            @functools.wraps(fn)
            def wrapper(*args, **kwargs):
                try:
                    return fn(*args, **kwargs)
                except BaseException as exc:
                    # If an error occurs and cancel_on_error is True,
                    # mark that an error occurred
                    if self._cancel_on_error:
                        with self._lock:
                            if not self._error_occurred:
                                self._error_occurred = True
                                self._first_exception = exc
                                # Cancel all pending futures
                                for fut in list(self._futures):
                                    if not fut.done() and not fut.cancelled():
                                        fut.cancel()
                    # Re-raise the exception
                    raise

            # Submit the wrapper function instead of the original
            future = super().submit(wrapper, *args, **kwargs)

            # Track the future if cancel_on_error is enabled
            if self._cancel_on_error:
                self._futures.add(future)

                # Add a callback to remove the future from our tracking set when it's done
                def _cleanup_future(fut):
                    with self._lock:
                        self._futures.discard(fut)
                        # If this future raised an exception, cancel all other futures
                        if fut.done() and not fut.cancelled():
                            try:
                                exc = fut.exception()
                                if exc is not None and not self._error_occurred:
                                    self._error_occurred = True
                                    self._first_exception = exc
                                    for f in list(self._futures):
                                        if not f.done() and not f.cancelled():
                                            f.cancel()
                            except (futures.CancelledError, Exception):
                                pass

                future.add_done_callback(_cleanup_future)

        return future

